    "Incorreta (B). Esta opção não condiz com as exigências teóricas ou matemáticas da questão. A resposta correta e comprovada pelos fundamentos da matéria é a alternativa C.",
    "Correta (C). Conforme a resolução: Tempo gasto na primeira metade: $\\Delta t_1 = \\frac{d/2}{80} = \\frac{d}{160}$. Tempo gasto na segunda metade: $\\Delta t_2 = \\frac{d/2}{60} = \\frac{d}{120}$. Tempo total: $\\Delta t = \\frac{d}{160} + \\frac{d}{120} = \\frac{7d}{480}$. Velocidade escalar média no percurso todo: $v_m = \\frac{d}{\\Delta t} = \\frac{d}{7d/480} = \\frac{480}{7} \\approx 68{,}6\\ \\mathrm{km/h}$.",
