  "subject": "Física",
  "content": "Dinâmica e leis de Newton",
  "detail": "Dinâmica e leis de Newton",
  "difficulty": "Média",
  "statement": "Um vaso de flores de massa total igual a 4,8 kg está pendurado, em equilíbrio, em um suporte preso a uma parede vertical. O suporte está pendurado em um parafuso preso ao ponto A e apoiado na parede no ponto B, conforme representado na figura.\n\n(www.ebanataw.com.br. Adaptado.)",
  "blockTypes": [
    "prose",
    "source",
    "command"
  ],
  "alternatives": [
    "60 N.",
    "80 N.",
    "20 N.",
    "40 N.",
    "100 N."
  ],
  "answer": "B",
  "annulled": false,
