  "answer": "B",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "Inicialmente vamos localizar a carga fonte Q1, gerado - ra do campo elétrico em F e G. Para isso basta traçar a reta suporte (linha tracejada) dos vetores →EF e →EG como mostra a figura a seguir. Encontramos o ponto 2 na intersecção das retas e po - sicio namos a carga puntiforme Q1, que é positiva. Na figura a seguir representamos o eixo de abscissas com os respectivos vetores →E1 e →E2, gerados pela carga fonte Q1 e pela segunda carga Q2, em P. Para que →E2 anule →E1, a carga Q2 deverá estar à direita de P. Como Q2 = Q1, concluímos que o ponto P está no ponto médio do segmento ––––– Q1Q2. Logo, a posição de Q2 é a do ponto 4."
  ],
  "resolutionMatched": true,
  "correctionOrigin": "official",
  "sourceSha256": "491c5b46e4779624fbb4da7fb907561919598a40247f6b40275feda6182ba5b1",
