  "annulmentNoValidAnswer": false,
  "resolution": [
    "$R_{\\text{eq}} = \\frac{36}{2} = 18\\ \\mathrm{\\Omega} \\implies R_{CB} = 18 - 6 = 12\\ \\mathrm{\\Omega}$. Em paralelo: $\\frac{30R}{30+R} = 12 \\implies R = 20\\ \\mathrm{\\Omega}$."
  ],
  "resolutionMatched": true,
