    "Incorreta (C). Esta opção não condiz com as exigências teóricas ou matemáticas da questão. A resposta correta e comprovada pelos fundamentos da matéria é a alternativa D.",
    "Correta (D). Conforme a resolução: Pela Lei de Ohm nos terminais do gerador: $U = R_{\\text{eq}} \\cdot i \\implies 36 = R_{\\text{eq}} \\cdot 2 \\implies R_{\\text{eq}} = 18\\ \\mathrm{\\Omega}$. Sabendo que $R_{AB} = R_{AC} + R_{CB} \\implies 18 = 6 + R_{CB} \\implies R_{CB} = 12\\ \\mathrm{\\Omega}$. A associação em paralelo do resistor de $30\\ \\mathrm{\\Omega}$ com a resistência $R$ da caixa resulta em: $R_{CB} = \\frac{30 R}{30 + R} = 12 \\implies 30R = 360 + 12R \\implies 18R = 360 \\implies R = 20\\ \\mathrm{\\Omega}$.",
    "Incorreta (E). Esta opção não condiz com as exigências teóricas ou matemáticas da questão. A resposta correta e comprovada pelos fundamentos da matéria é a alternativa D."
