    "Correta (B). Conforme a resolução: A alternativa correta reporta-se à primeira parte do texto transcrito, quando Caminha enfatiza a urgência de informar o rei de Portugal acerca da descoberta de uma nova terra, para que o soberano pudesse mandar explorá-la (no sentido de aumentar o conhecimento sobre ela), antes que a frota cabralina retornasse das Índias. A segunda parte do excerto, referente ao contato entre europeus e indígenas, representantes de culturas distintas, não foi considerada pelo examinador. Obs.: A transcrição da carta de Caminha errou ao grafar “degradados” (rebaixados, reduzidos a uma condição de indignidade), quando a forma correta seria “degredados” (desterrados, banidos, exilados).",
