  "id": "famerp2016-p1-q49",
  "n": 49,
  "subject": "História",
  "content": "Brasil República",
  "detail": "Brasil República",
  "difficulty": "Média",
  "statement": "O Plano de Metas foi uma experiência sistemática de planejamento implementada pelo governo Juscelino Kubitschek (1956-1961). O Plano favoreceu a instalação de empresas estrangeiras especializadas na montagem de automóveis no Brasil, fato que",
  "blockTypes": [
    "command"
  ],
  "alternatives": [
    "mudou a estrutura econômica do país, devido à destruição do antigo parque automobilístico brasileiro.",
    "enfraqueceu a capacidade do Estado brasileiro em garantir os direitos dos trabalhadores urbanos.",
    "promoveu uma expansão da economia industrial com o surgimento de fábricas de autopeças.",
    "concentrou a produção em um setor econômico em prejuízo das indústrias de produtos eletrônicos e de outros bens de consumo duráveis.",
    "permitiu a exploração de todas as etapas da produção dos veículos pelos empresários estrangeiros."
  ],
  "answer": "C",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "A questão destaca um aspecto do plano de governo de Juscelino Kubitschek, constituído por 31 metas: o desenvolvimento da indústria automobilística no Brasil. Juntamente com a abertura de rodovias, os projetos de hidrelétricas e a construção de Brasília, a implantação do parque automobilístico brasileiro foi um dos pontos altos do projeto desenvolvimentista de JK, sintetizado no célebre slogan de “Cincoenta anos de progresso em cinco de governo”."
  ],
  "resolutionMatched": true,
